// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Existing immutable queue integration consumer.
// @spec: COR
// @consumers: inputs/brief.md
import { selectBatch } from './queue.ts';
/** @purpose Preserve duplicate jobs and input order. | @returns Chosen jobs and unchanged input. */
export function nextJobs(): { selected: string[]; original: string[] } { const jobs = ['a', 'a', 'b']; return { selected: selectBatch(jobs, 2), original: jobs }; }

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { selectBatch } from './queue.ts';

function assertTypeError(run: () => unknown, messagePattern: RegExp): void {
  assert.throws(run, (error: unknown) => {
    assert.ok(error instanceof TypeError);
    assert.match((error as Error).message, messagePattern);
    return true;
  });
}

test('[COR-REQ-1] public behavior', () => {
  // contract: leading entries, in order, duplicates preserved
  assert.deepStrictEqual(selectBatch(['a', 'a', 'b', 'c'], 2), ['a', 'a']);

  // contract: result is a fresh array that does not alias the input
  const input = ['a', 'b', 'c'];
  const selected = selectBatch(input, 2);
  assert.deepStrictEqual(selected, ['a', 'b']);
  assert.notStrictEqual(selected, input);

  // invariant: the input array is unchanged in content and order
  assert.deepStrictEqual(input, ['a', 'b', 'c']);

  // boundary: zero capacity returns an empty array
  assert.deepStrictEqual(selectBatch(['a', 'b'], 0), []);

  // boundary: capacity larger than the input returns every entry as a fresh copy
  const shortQueue = ['x', 'y'];
  const everything = selectBatch(shortQueue, 10);
  assert.deepStrictEqual(everything, ['x', 'y']);
  assert.notStrictEqual(everything, shortQueue);
  assert.deepStrictEqual(shortQueue, ['x', 'y']);

  // boundary: valid zero capacity on empty input returns an empty array
  assert.deepStrictEqual(selectBatch([], 0), []);
});

test('[COR-REQ-2] invalid input', () => {
  // failure mode: any non-array runtime input is rejected
  assertTypeError(() => selectBatch('not-an-array' as unknown as string[], 1), /array of strings/);
  assertTypeError(() => selectBatch(null as unknown as string[], 1), /array of strings/);
  assertTypeError(() => selectBatch(undefined as unknown as string[], 1), /array of strings/);
  assertTypeError(() => selectBatch({} as unknown as string[], 1), /array of strings/);

  // failure mode: any non-string entry is rejected, including mixed arrays
  assertTypeError(() => selectBatch([1] as unknown as string[], 1), /entry must be a string/);
  assertTypeError(() => selectBatch(['a', null] as unknown as string[], 2), /entry must be a string/);
  assertTypeError(() => selectBatch(['a', 2, 'b'] as unknown as string[], 3), /entry must be a string/);

  // failure mode: negative, fractional, and non-finite capacities are rejected
  assertTypeError(() => selectBatch([], -1), /nonnegative integer/);
  assertTypeError(() => selectBatch([], 1.5), /nonnegative integer/);
  assertTypeError(() => selectBatch([], Number.POSITIVE_INFINITY), /nonnegative integer/);
  assertTypeError(() => selectBatch([], Number.NEGATIVE_INFINITY), /nonnegative integer/);
  assertTypeError(() => selectBatch([], Number.NaN), /nonnegative integer/);

  // invariant: a rejected call leaves the input array and its order untouched
  const input = ['a', 'b', 'c'];
  const snapshot = [...input];
  assertTypeError(() => selectBatch(input, -1), /nonnegative integer/);
  assert.deepStrictEqual(input, snapshot);
  assert.strictEqual(input.length, 3);
});

// @file: Deterministic immutable batch selection for queue consumers.
// @spec: COR
// @consumers: nextJobs

/**
 * @purpose Select the leading queue entries as a fresh ordered array.
 * @param values Queue of job strings; never mutated.
 * @param capacity Nonnegative integer count of leading entries to select.
 * @throws {TypeError} `values` is not an array, holds a non-string, or `capacity` is negative, fractional, or non-finite.
 * @returns New array with the first `capacity` entries, preserving order and duplicates.
 * @post `values` is unchanged and shares no reference with the result.
 */
export function selectBatch(values: readonly string[], capacity: number): string[] {
  // #region START_VALIDATE_PUBLIC_INPUT — failure mode: TypeScript annotations are not runtime validation, so every contract rejection happens before selection
  if (!Array.isArray(values)) {
    throw new TypeError('[selectBatch] values must be an array of strings');
  }

  for (const entry of values) {
    if (typeof entry !== 'string') {
      throw new TypeError(`[selectBatch] values entry must be a string, received ${typeof entry}`);
    }
  }

  if (!Number.isInteger(capacity) || capacity < 0) {
    throw new TypeError(`[selectBatch] capacity must be a nonnegative integer, received ${String(capacity)}`);
  }
  // #endregion END_VALIDATE_PUBLIC_INPUT

  return values.slice(0, capacity);
}
